-- Hand-written: Prisma's DSL can't express these CHECK constraints or the partial index.

-- AddCheckConstraint (#1645)
ALTER TABLE "Item" ADD CONSTRAINT "Item_scope_key_agreement_check"
  CHECK (
    ("scope" = 'GLOBAL' AND "campaignId" IS NULL AND "scopeKey" = 'global')
    OR
    ("scope" = 'CAMPAIGN' AND "campaignId" IS NOT NULL AND "scopeKey" = 'campaign:' || "campaignId")
  );

-- AddCheckConstraint (#1795)
ALTER TABLE "CatalogEntry" ADD CONSTRAINT "CatalogEntry_owner_scope_check"
  CHECK (
    ("scope" = 'GLOBAL' AND "ownerUserId" IS NULL AND "ownerCampaignId" IS NULL)
    OR
    ("scope" = 'USER' AND "ownerUserId" IS NOT NULL AND "ownerCampaignId" IS NULL)
    OR
    ("scope" = 'CAMPAIGN' AND "ownerCampaignId" IS NOT NULL AND "ownerUserId" IS NULL)
  );

-- AddCheckConstraint (#1565)
ALTER TABLE "StartingEquipmentPackage" ADD CONSTRAINT "StartingEquipmentPackage_class_xor_background_check"
  CHECK (
    ("classId" IS NOT NULL AND "backgroundId" IS NULL)
    OR
    ("classId" IS NULL AND "backgroundId" IS NOT NULL)
  );

-- AddCheckConstraint (#1564)
ALTER TABLE "StartingEquipmentPackage" ADD CONSTRAINT "StartingEquipmentPackage_gold_dice_jointly_null_check"
  CHECK (
    ("goldDiceCount" IS NULL AND "goldDiceFaces" IS NULL AND "goldMultiplier" IS NULL)
    OR
    ("goldDiceCount" IS NOT NULL AND "goldDiceFaces" IS NOT NULL AND "goldMultiplier" IS NOT NULL)
  );

-- AddCheckConstraint (#1531)
ALTER TABLE "Subclass" ADD CONSTRAINT "Subclass_casterFraction_spellcastingAbility_copresence"
  CHECK (("casterFraction" IS NULL) = ("spellcastingAbility" IS NULL));

-- CreateIndex: at most one active session per campaign.
CREATE UNIQUE INDEX "Session_campaignId_active_key"
  ON "Session"("campaignId")
  WHERE "status" = 'active' AND "campaignId" IS NOT NULL;

-- AddForeignKey (#1571): Spell.catalogEntryId is a deliberately relationless
-- scalar, so `prisma migrate diff`/`migrate dev` always emits a DROP for this FK.
-- Strip that DROP from every future generated migration.
ALTER TABLE "Spell" ADD CONSTRAINT "Spell_catalogEntryId_fkey" FOREIGN KEY ("catalogEntryId") REFERENCES "CatalogEntry"("id") ON DELETE CASCADE ON UPDATE CASCADE;
